# ──────────────────────────────────────────────────────────────
# 헬퍼 함수
# ──────────────────────────────────────────────────────────────
def get_tickers_by_sector(sector: str) -> list:
    """특정 섹터의 ticker 리스트 반환"""
    return [t for t, v in ticker_sector_map.items() if v['sector'] == sector]


def get_tickers_by_min_mktcap(min_b: float) -> list:
    """시가총액 기준 필터링 (단위: B USD)"""
    return [t for t, v in ticker_sector_map.items() if v['mktCap_B'] >= min_b]


def sector_summary() -> dict:
    """섹터별 ticker 수 반환"""
    from collections import Counter
    return dict(Counter(v['sector'] for v in ticker_sector_map.values()))


